#include <stdio.h>
#include <string.h>

/* Same enum as the candidate's file. */
enum gpio_op { GPIO_SET, GPIO_CLEAR, GPIO_TOGGLE };

/* Provided by the candidate in solution.c */
unsigned int gpio_apply(unsigned int reg, enum gpio_op op, unsigned int mask);

int main(void)
{
    unsigned int reg;
    if (scanf("%x", &reg) != 1) {
        return 1;
    }

    char opname[8];
    unsigned int mask;
    while (scanf("%7s %x", opname, &mask) == 2) {
        enum gpio_op op;

        if (strcmp(opname, "SET") == 0) {
            op = GPIO_SET;
        } else if (strcmp(opname, "CLR") == 0) {
            op = GPIO_CLEAR;
        } else if (strcmp(opname, "TOG") == 0) {
            op = GPIO_TOGGLE;
        } else {
            printf("UNKNOWN OP %s\n", opname);
            return 1;
        }

        reg = gpio_apply(reg, op, mask);
        printf("%08X\n", reg);
    }
    return 0;
}
